// ============================================================
// Fish Audio 语音脚本(酒馆助手 · 全局脚本)
// 功能:角色回复自动朗读,声音由下方 VOICE_DB(声音数据库)决定
// 依赖:酒馆服务端插件 fish-tts(plugins/fish-tts/,随酒馆自动加载)
// ============================================================

const API_URL = "/api/plugins/fish_tts/tts"; // 酒馆服务端插件(同源,无需本地服务)
const MAX_LEN = 500;                    // 单条朗读最大字数(防止长文刷爆)

// ---- 声音数据库:聊天里显示的角色名 → 声音名(voices.json 里的键) ----
const VOICE_DB = {
  "瑟琳": "瑟琳",
  // 想加更多角色,照这个格式: "聊天里的角色名": "voices.json里的声音名",
  "*": "瑟琳", // 兜底:没收录的角色也用这个声音;不想让陌生角色出声就删掉这行
};

// ---- 状态(存脚本变量,重开酒馆会记住) ----
let enabled = true;
try {
  const v = await getVariables({ type: "script" });
  enabled = v?.fish_tts_enabled !== false;
} catch (e) { /* 变量 API 不可用时默认开启 */ }

// ---- 文本清洗:去思考块/代码块/标签/符号,只留能念的 ----
function cleanText(raw) {
  return String(raw || "")
    .replace(/<think(?:ing)?>[\s\S]*?<\/think(?:ing)?>/gi, "")
    .replace(/```[\s\S]*?```/g, "")
    .replace(/<[^<>\n]{1,120}>/g, " ")
    .replace(/[*_~`#>|]+/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, MAX_LEN);
}

// ---- 朗读队列:消息连发时按顺序播,不抢 ----
let chain = Promise.resolve();
function enqueue(job) {
  chain = chain.then(job).catch((err) => {
    console.error("[FishTTS] 播放出错:", err);
    setStatus("出错:" + String(err && err.message || err).slice(0, 80));
  });
}

// ---- 调酒馆插件合成并播放 ----
async function speak(text, voiceName) {
  const resp = await fetch(API_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ text, voice: voiceName }),
  });
  if (resp.status === 404) {
    throw new Error("服务端插件未安装或未生效:请把本仓库克隆到酒馆 plugins/ 目录并重启酒馆(见 README)");
  }
  if (!resp.ok) {
    throw new Error("桥接返回 HTTP " + resp.status + " " +
      String(await resp.text()).slice(0, 100));
  }
  const url = URL.createObjectURL(await resp.blob());
  const audio = new Audio(url);
  audio.onended = () => URL.revokeObjectURL(url);
  await audio.play();
}

async function speakMessage(messageId) {
  if (!enabled) return;
  const list = getChatMessages(messageId);
  const msg = Array.isArray(list) ? list[0] : list;
  if (!msg || msg.is_user || msg.is_system) return;
  const voice = VOICE_DB[msg.name] ?? VOICE_DB["*"];
  if (!voice) { setStatus(`角色「${msg.name}」未配置声音`); return; }
  const text = cleanText(msg.message);
  if (!text) return;
  setStatus(`朗读中:${msg.name}(${voice})…`);
  await speak(text, voice);
  setStatus(`上次朗读:${msg.name}`);
}

// ---- 事件:新消息到达 ----
const EVT = typeof tavern_events !== "undefined" ? tavern_events : {};
eventOn(EVT.MESSAGE_RECEIVED || "MESSAGE_RECEIVED", (messageId) => {
  enqueue(() => speakMessage(messageId));
});

// ---- 悬浮面板(画在酒馆主页面上) ----
let statusEl = null;
function setStatus(text) {
  if (statusEl) statusEl.textContent = text;
}

try {
  const pdoc = (window.parent && window.parent.document) || document;
  const OLD = pdoc.getElementById("fish-tts-panel");
  if (OLD) OLD.remove();

  const panel = pdoc.createElement("div");
  panel.id = "fish-tts-panel";
  panel.style.cssText = [
    "position:fixed", "right:16px", "bottom:16px", "z-index:99999",
    "background:rgba(20,22,30,.92)", "color:#e8eaf0", "border-radius:12px",
    "padding:10px 12px", "font-size:12px", "line-height:1.6",
    "box-shadow:0 4px 16px rgba(0,0,0,.35)", "width:210px",
    "font-family:inherit", "user-select:none",
  ].join(";");

  const title = pdoc.createElement("div");
  title.textContent = "🔊 Fish 语音";
  title.style.cssText = "font-weight:600;margin-bottom:6px;cursor:pointer;";
  panel.appendChild(title);

  const body = pdoc.createElement("div");

  const row1 = pdoc.createElement("label");
  row1.style.cssText = "display:flex;align-items:center;gap:6px;cursor:pointer;";
  const toggle = pdoc.createElement("input");
  toggle.type = "checkbox";
  toggle.checked = enabled;
  const toggleText = pdoc.createElement("span");
  toggleText.textContent = "自动朗读新回复";
  row1.append(toggle, toggleText);
  body.appendChild(row1);

  const listenBtn = pdoc.createElement("button");
  listenBtn.textContent = "▶ 试听瑟琳";
  listenBtn.style.cssText = [
    "margin-top:6px", "border:none", "border-radius:8px", "padding:4px 10px",
    "cursor:pointer", "background:#4a7dff", "color:#fff", "font-size:12px",
  ].join(";");
  body.appendChild(listenBtn);

  const dbInfo = pdoc.createElement("div");
  dbInfo.style.cssText = "opacity:.65;margin-top:6px;";
  dbInfo.textContent = "声音库:" +
    Object.entries(VOICE_DB).filter(([k]) => k !== "*")
      .map(([k, v]) => (k === v ? k : `${k}→${v}`)).join("、") +
    (VOICE_DB["*"] ? "(含兜底)" : "");
  body.appendChild(dbInfo);

  statusEl = pdoc.createElement("div");
  statusEl.style.cssText = "opacity:.85;margin-top:4px;min-height:18px;";
  statusEl.textContent = enabled ? "已启用" : "已关闭";
  body.appendChild(statusEl);

  panel.appendChild(body);

  toggle.addEventListener("change", async () => {
    enabled = toggle.checked;
    setStatus(enabled ? "已启用" : "已关闭");
    try {
      await replaceVariables({ fish_tts_enabled: enabled }, { type: "script" });
    } catch (e) { /* 记不住就记不住吧,本次会话内仍有效 */ }
  });

  listenBtn.addEventListener("click", () => {
    setStatus("试听中…");
    enqueue(async () => {
      await speak(cleanText("你好,我是瑟琳。酒馆语音测试,声音听起来怎么样?"),
        VOICE_DB["瑟琳"] || "瑟琳");
      setStatus("试听完成");
    });
  });

  title.addEventListener("click", () => {
    body.style.display = body.style.display === "none" ? "" : "none";
  });

  pdoc.body.appendChild(panel);
} catch (e) {
  console.error("[FishTTS] 悬浮面板创建失败(不影响自动朗读):", e);
}

console.log("[FishTTS] 已加载 | 桥接:", BRIDGE, "| 声音库:", Object.keys(VOICE_DB).join(", "));
